/** Headers generated by the composer, including drafts written in either locale. */
export function isComposerHistoryIntro(text: string): boolean {
  return /^(?:On .+ wrote:|Am .+ schrieb .+:|---------- (?:Forwarded message|Weitergeleitete Nachricht) ----------)$/.test(text.trim());
}

export function hasComposerHtmlHistory(html: string | null): boolean {
  if (!html) return false;
  const template = document.createElement('template');
  template.innerHTML = html;
  return [...template.content.querySelectorAll('blockquote')]
    .some((quote) => isComposerHistoryIntro(quote.firstElementChild?.textContent ?? ''));
}

function historyTextRanges(text: string): Array<{ from: number; to: number }> {
  const lines = text.split('\n');
  const ranges: Array<{ from: number; to: number }> = [];
  let offset = 0;
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index]!;
    if (!isComposerHistoryIntro(line)) {
      offset += line.length + 1;
      continue;
    }
    const from = offset;
    // Reply quotes have explicit > markers. Text converted from HTML and
    // forwarded messages have no end marker and occupy the remaining body.
    if (!lines[index + 1]?.trimStart().startsWith('>')) {
      ranges.push({ from, to: text.length });
      break;
    }
    offset += line.length + 1;
    while (index + 1 < lines.length && (!lines[index + 1]!.trim() || lines[index + 1]!.trimStart().startsWith('>'))) {
      index++;
      offset += lines[index]!.length + 1;
    }
    ranges.push({ from, to: Math.min(offset, text.length) });
  }
  return ranges;
}

export function hasComposerTextHistory(text: string): boolean {
  return historyTextRanges(text).length > 0;
}

export function removeComposerTextHistory(text: string): string {
  let result = text;
  for (const range of historyTextRanges(text).reverse()) {
    result = result.slice(0, range.from) + result.slice(range.to);
  }
  return result.trimEnd();
}
